import { useState } from 'react'
import { Button } from 'moru-ui'
import { Command } from 'moru-ui'

export function QuickActions() {
  const [view, setView] = useState('Projects')
  return (
    <div>
      <Command
        title="Go to"
        trigger={<Button type="button">Open commands</Button>}
        items={[
          {
            id: 'projects',
            label: 'Projects',
            keywords: ['work'],
            onSelect: () => setView('Projects'),
          },
          { id: 'team', label: 'Team', keywords: ['people'], onSelect: () => setView('Team') },
        ]}
      />
      <p role="status">Current view: {view}</p>
    </div>
  )
}
